"""KiCad netlist + ngspice on a schematic generated by sparky, against the analytic RC low-pass (R = 1k, C = 100n, fc = 1/(2 pi R C) = 1591.55 Hz)."""
import math

import numpy as np
import pytest

from conftest import needs_kicad_libs
from sparky.analysis import simulate

pytestmark = [needs_kicad_libs, pytest.mark.skipif(not simulate.available(), reason="kicad-cli / ngspice missing")]

R, C = 1e3, 100e-9
FC = 1 / (2 * math.pi * R * C)


@pytest.fixture(scope="module")
def net(tmp_path_factory):
    from sparky.circuits import reset, skidl
    from sparky.circuits.passives import passive
    from sparky.design import from_skidl
    from sparky.export.kicad_project import write_lib_tables
    from sparky.export.kicad_sch import write_kicad_sch
    d = tmp_path_factory.mktemp("rc")
    reset()
    s = skidl()
    gnd, vin, vout = s.Net("GND"), s.Net("VIN"), s.Net("VOUT")
    src = s.Part("Simulation_SPICE", "VSIN", footprint="TestPoint:TestPoint_Pad_D1.5mm")
    src[1] += vin
    src[2] += gnd
    vin & passive("R", R, "0603") & vout & passive("C", C, "0603") & gnd
    c = from_skidl(name="rc")
    write_kicad_sch(c, d / "rc.kicad_sch")
    write_lib_tables(c, d)
    return simulate.netlist(d / "rc.kicad_sch")


def test_netlist_holds_the_parts_with_their_values(net):
    assert "R1 VIN VOUT 1k" in net and "C1 VOUT GND 100n" in net


def test_ac_response_matches_the_analytic_low_pass(net):
    n = simulate.set_source(net, "V1", "dc 0 ac 1")
    r = simulate.run(n, ".ac dec 50 10 1meg", ["v(vout)"])
    h = r["v(vout)"]
    expect = 1 / (1 + 1j * r["x"] / FC)
    assert np.abs(h) == pytest.approx(np.abs(expect), rel=1e-3)
    i = int(np.argmin(np.abs(r["x"] - FC)))
    assert abs(h[i]) == pytest.approx(1 / math.sqrt(2), rel=0.03)                     # -3 dB at the corner (grid point nearest fc)
    assert np.degrees(np.angle(h[i])) == pytest.approx(-45, abs=2.5)


def test_step_response_matches_one_minus_exp(net):
    n = simulate.set_source(net, "V1", "pulse(0 1 0 1n 1n 1 2)")
    r = simulate.run(n, ".tran 1u 500u", ["v(vout)"])
    t = r["x"]
    assert r["v(vout)"] == pytest.approx(1 - np.exp(-t / (R * C)), abs=5e-3)


def test_unknown_source_is_an_error(net):
    with pytest.raises(KeyError):
        simulate.set_source(net, "V9", "dc 1")
